import{_ as a,d as r,e as t,x as n}from"./chunks/framework.BRr8VP3a.js";const f=JSON.parse('{"title":"Hurricane Ian: the cone describes the center’s track","description":"Track uncertainty, storm surge, and evacuation decisions are different targets.","frontmatter":{"title":"Hurricane Ian: the cone describes the center’s track","description":"Track uncertainty, storm surge, and evacuation decisions are different targets.","kind":"Documented case","source_type":"Official retrospective report and contemporaneous forecast products"},"headers":[],"relativePath":"en/cases/representation-hurricane-cone.md","filePath":"en/cases/representation-hurricane-cone.md"}'),o={name:"en/cases/representation-hurricane-cone.md"};function s(i,e,c,h,d,l){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="hurricane-ian-the-cone-describes-the-center-s-track" tabindex="-1">Hurricane Ian: the cone describes the center’s track <a class="header-anchor" href="#hurricane-ian-the-cone-describes-the-center-s-track" aria-label="Permalink to &quot;Hurricane Ian: the cone describes the center’s track&quot;">​</a></h1><p>Hurricane Ian made landfall at Cayo Costa in southwest Florida on September 28, 2022. The National Hurricane Center’s retrospective report records catastrophic storm surge. Reading that report alongside the 2022 cone definition helps identify what a representation was designed to answer.</p><h2 id="use-the-definition-from-the-event-s-year" tabindex="-1">Use the definition from the event’s year <a class="header-anchor" href="#use-the-definition-from-the-event-s-year" aria-label="Permalink to &quot;Use the definition from the event’s year&quot;">​</a></h2><p>The <a href="https://web.archive.org/web/20220926140803/https://www.nhc.noaa.gov/aboutcone.shtml" target="_blank" rel="noreferrer">September 26, 2022 archived definition</a> describes the cone as the probable track of a tropical cyclone’s <strong>center</strong>. Its circles used the previous five years of official forecast errors, with two-thirds of those errors falling within the relevant circles. The 2022 radii were based on 2017–2021 errors.</p><p>That definition does not describe the extent of wind, rainfall, or storm surge. The circles are not a statement that impacts stop at the cone boundary. Their historical error basis also should not be silently replaced by a later year’s radii.</p><h2 id="what-the-ian-report-records" tabindex="-1">What the Ian report records <a class="header-anchor" href="#what-the-ian-report-records" aria-label="Permalink to &quot;What the Ian report records&quot;">​</a></h2><p>NHC reports that the landfall location lay inside the cone for every forecast cycle, while also reporting substantial track errors and difficulty forecasting the precise southwest Florida landfall location. This is NHC’s retrospective evaluation of its own forecasts, not a claim of error-free prediction. See the <a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer">Ian report</a>, page 15 and Figure 27 on page 67.</p><p>The same report records markedly different water levels over short distances: 12.70 feet above mean higher high water at Fort Myers Beach and 4.47 feet at Pirate Harbor, less than 30 miles away. It describes a sharp cross-track surge gradient and sensitivity to the precise storm track (pages 8–9 and 16).</p><p>Surge watches, warnings, and peak forecasts addressed that other target. At Fort Myers Beach, the peak forecast rose from 4–7 feet above ground to 8–12 feet and eventually 12–18 feet as track and intensity information changed. Above-ground forecasts and sensor levels relative to mean higher high water have different reference levels; the report makes an approximate comparison near the immediate coast (pages 8 and 15–16).</p><h2 id="read-the-task-boundary" tabindex="-1">Read the task boundary <a class="header-anchor" href="#read-the-task-boundary" aria-label="Permalink to &quot;Read the task boundary&quot;">​</a></h2><p><a href="/xi-kari-skill/handbook/en/theory/part-03.html#section-3-4">§3.4</a> requires a sufficiency judgment to specify its query or task family, horizon, environment, and admissible operations. A representation of the center’s likely track cannot alone answer a particular coast’s water-height question. NHC supplied separate products for separate hazards.</p><p><a href="/xi-kari-skill/handbook/en/theory/part-04.html#section-4-18-1">F1</a> gives a formal condition for recovering a target from a representation. This case illustrates the relevance of matching representation to task; it is not a formal empirical test of F1. The page supplies neither a complete state space and mapping nor paired records establishing identical cones with different surge answers.</p><h2 id="forecast-evidence-is-not-evidence-of-every-decision" tabindex="-1">Forecast evidence is not evidence of every decision <a class="header-anchor" href="#forecast-evidence-is-not-evidence-of-every-decision" aria-label="Permalink to &quot;Forecast evidence is not evidence of every decision&quot;">​</a></h2><p>Pre-landfall <a href="https://www.nhc.noaa.gov/archive/2022/al09/al092022.discus.018.shtml" target="_blank" rel="noreferrer">Discussion 18</a> and <a href="https://www.nhc.noaa.gov/archive/2022/al09/al092022.discus.020.shtml" target="_blank" rel="noreferrer">Discussion 20</a> warned against focusing solely on the exact track and directed residents to local advice and evacuation orders. These texts do not establish how individual residents understood the cone or what caused their choices.</p><p>The report’s judgment that a broad warning was warranted under the uncertainty at issuance is distinct from the observed extent of inundation. A forecast’s accuracy, the causal effect of protective action, and valid authority to order action each require their own inquiry.</p><h2 id="sources-and-version" tabindex="-1">Sources and version <a class="header-anchor" href="#sources-and-version" aria-label="Permalink to &quot;Sources and version&quot;">​</a></h2><ul><li>Lisa Bucci and colleagues, <a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer"><em>Tropical Cyclone Report: Hurricane Ian (AL092022), 23–30 September 2022</em></a>, NHC, March 12, 2026 revision; pages cited above. The revision notes removal of mixed measured/estimated WeatherStem data from the relevant observation material.</li><li>NHC, <a href="https://web.archive.org/web/20220926140803/https://www.nhc.noaa.gov/aboutcone.shtml" target="_blank" rel="noreferrer">2022 cone definition</a>, and Discussions 18 and 20, September 27, 2022.</li></ul><p>Read <a href="./../concepts/representation.html">representation</a> and <a href="./../concepts/prediction.html">prediction under intervention</a>.</p>',18)])])}const u=a(o,[["render",s]]);export{f as __pageData,u as default};
